<template><view class="strategy-notebook"><text class="notebook-hint">手记先存在自己的人生存档，可复制文本分享。圈子联网发布尚未开放。</text><view class="notebook-tabs"><button :class="{active:tab==='drafts'}" @click="tab='drafts'">我的草稿</button><button :class="{active:tab==='examples'}" @click="tab='examples'">示例策略</button><button :class="{active:tab==='import'}" @click="tab='import'">导入</button></view><view v-if="tab==='import'"><textarea v-model="importText" class="strategy-input" maxlength="6000" placeholder="粘贴朋友主动分享的策略文本，不会执行其中的操作" /><button class="strategy-button" :disabled="busy || !importText.trim()" @click="importTextDraft">存为草稿</button></view><template v-else><text v-if="tab==='drafts'&&!state.homestead.drafts.length" class="notebook-hint">还没有草稿。先复制一份示例，再改成自己的安排。</text><view v-for="d in list" :key="d.id" class="strategy-card"><template v-if="editing===d.id"><view v-for="f in fields" :key="f.key" class="strategy-field"><text>{{f.name}}</text><textarea v-model="form[f.key]" :maxlength="f.key==='steps'?600:f.key==='result'?400:f.key==='title'?60:200" auto-height class="strategy-input" /></view><view class="strategy-actions"><button :disabled="busy" @click="saveDraft(d.id)">保存</button><button @click="editing=''">取消</button></view></template><template v-else><text class="strategy-title">{{d.title}}</text><text class="notebook-hint">{{d.source}} · {{d.version}}</text><text v-if="d.version!==HOMESTEAD_RULES" class="notebook-hint">基于其他版本，购买前请核对当前规则。</text><view v-for="f in fields.slice(1)" :key="f.key" class="strategy-field"><text>{{f.name}}：{{d[f.key] || (f.key==='result'?'尚未填写实际结果':'未填写')}}</text></view><view class="strategy-actions"><button :disabled="busy" @click="copy(d.id)">复制草稿</button><button v-if="tab==='drafts'" @click="edit(d)">修改</button><button v-if="tab==='drafts'" @click="share(d.id)">复制分享</button><button v-if="tab==='drafts'" @click="remove(d.id)">{{deleting===d.id?'确认删除':'删除'}}</button></view></template></view></template></view></template>
<script setup>
import {ref,computed} from 'vue'
import {state,toast} from '../game/engine/core.js'
import {STRATEGIES,copyStrategy,saveStrategy,removeStrategy,strategyShareText,importStrategy} from '../game/engine/homestead.js'
import {HOMESTEAD_RULES} from '../game/data/homestead.js'
import {useAction} from '../game/use-action.js'
const {busy,run}=useAction(),tab=ref('drafts'),editing=ref(''),deleting=ref(''),form=ref({}),importText=ref('')
const fields=[{key:'title',name:'标题'},{key:'goal',name:'目标'},{key:'conditions',name:'条件'},{key:'steps',name:'步骤'},{key:'budget',name:'预算'},{key:'tradeoff',name:'取舍'},{key:'result',name:'实际结果'}]
const list=computed(()=>tab.value==='examples'?STRATEGIES:state.homestead.drafts)
function copy(id){run(()=>{const ok=copyStrategy(id);if(ok)tab.value='drafts';return ok})}
function edit(d){form.value={...d};editing.value=d.id;deleting.value=''}
function saveDraft(id){run(()=>{const ok=saveStrategy(id,form.value);if(ok)editing.value='';return ok})}
function remove(id){if(deleting.value!==id){deleting.value=id;return}run(()=>{const ok=removeStrategy(id);if(ok)deleting.value='';return ok})}
function share(id){const text=strategyShareText(id);if(text)uni.setClipboardData({data:text,success:()=>toast('已复制手记文本，可自行分享给朋友'),fail:()=>toast('未能复制，请检查剪贴板权限')})}
function importTextDraft(){run(()=>{const ok=importStrategy(importText.value);if(ok){importText.value='';tab.value='drafts'}return ok})}
</script>
<style scoped>.notebook-hint{display:block;font-size: max(var(--readable-min, 0px), 11px);line-height:1.7;color:var(--muted);margin:6px 0}.notebook-tabs,.strategy-actions{display:flex;gap:5px;flex-wrap:wrap;margin:10px 0}.notebook-tabs button{flex:1}.notebook-tabs button,.strategy-actions button,.strategy-button{margin:0;padding:7px 10px;font-size: max(var(--readable-min, 0px), 11px);line-height:1.4;color:var(--ink);background:var(--paper-deep)}.notebook-tabs .active,.strategy-button{background:var(--hud);color:#fff2d4}.strategy-card{padding:12px 0;border-bottom:1px solid var(--line)}.strategy-title{font-size:15px;font-weight:700}.strategy-field{font-size: max(var(--readable-min, 0px), 12px);line-height:1.7;margin:7px 0;white-space:pre-wrap;overflow-wrap:anywhere}.strategy-input{box-sizing:border-box;width:100%;min-height:66px;padding:8px;font-size: max(var(--readable-min, 0px), 12px);line-height:1.6;background:var(--card);border:1px solid var(--line);border-radius:5px;color:var(--ink)}</style>
